export const applied2027Questions: Question[] = rows.map(([chapter, topic, prompt, correct, wrong1, wrong2, wrong3, explanation], index) => ({
  id: `ap27-${String(index + 1).padStart(3, '0')}`, chapter, topic, prompt,
  choices: [correct, wrong1, wrong2, wrong3], answers: [0], explanation,
  reviewSection: `応用：${topic}`, examTrap: '状況と条件を踏まえて判断しましょう。',
  choiceNotes: [explanation, `誤答：${wrong1}`, `誤答：${wrong2}`, `誤答：${wrong3}`],
}))
